#include "all_your_base.h"

#include <cassert>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>

int main() {
    using digits_t = std::vector<unsigned int>;
    const auto max_u = std::numeric_limits<unsigned int>::max();

    assert((all_your_base::convert(2, digits_t{1, 0, 1, 0, 1, 0}, 10) == digits_t{4, 2}));
    assert((all_your_base::convert(10, digits_t{0, 0, 42, 0}, 2) == digits_t{1, 0, 1, 0, 1, 0}));
    assert((all_your_base::convert(16, digits_t{0, 0, 2, 10, 0}, 3) == digits_t{1, 1, 2, 0}));
    assert((all_your_base::convert(max_u, digits_t{max_u - 1}, max_u - 1) == digits_t{1, 0}));

    digits_t long_binary(200, 1);
    digits_t decimal = all_your_base::convert(2, long_binary, 10);
    assert(all_your_base::convert(10, decimal, 2) == long_binary);

    bool threw = false;
    try { all_your_base::convert(1, {}, 10); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    threw = false;
    try { all_your_base::convert(2, {}, 0); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    threw = false;
    try { all_your_base::convert(2, digits_t{1, 2, 1}, 10); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    threw = false;
    try { all_your_base::convert(2, digits_t{1}, 1); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);

    std::cout << "edge cases passed\n";
}
